for(const menu of megaMenus)for(const [group,items] of menu.groups)for(const [label,href] of items){const route=href.replace(/\/$/,'');if(pages[route]||localAliases.has(route))continue;const details=serviceDetails[route];const international=route.startsWith('/moving-to-');const location=menu.label==='Locations'&&!details;const removal=route.startsWith('/removals-');const type=international?'europe':location?(removal?'home':'storage'):menu.label==='Office'?(route.includes('storage')?'storage':'office'):menu.label==='Storage'?'storage':'home';const place=label.replace(/^Removals /,'');const title=details?.[0]||(international?`Moving to ${label}`:location?`${removal?'Removals':'Storage'} ${label}`:label);const headline=details?.[1]||(international?`Your move to ${label}, carefully planned.`:location?`A considered plan for ${place}.`:`${label}, made simpler.`);const intro=details?.[2]||(international?`Tell us the collection and delivery addresses, preferred dates and contents for your move to ${label}. Customs, border requirements and timing should be confirmed for your specific route.`:location?`Plan ${removal?'a move':'storage and collection'} in ${place}. Share the address, property access, parking, contents and preferred dates so the team can understand your requirements.`:`Tell us about your requirements, timing and property access so the team can discuss the right scope for your enquiry.`);pages[route]={title:`${title} | Removals and Storage X`,description:intro.slice(0,155),label:group,h1:headline,intro,kind:'destination',destination:{title,type,route,place,location,international}}}
function reviewsSection(){return `<section class="section verified-reviews"><div class="section-head"><div><span class="eyebrow">CUSTOMER EXPERIENCES</span><h2>Words from people<br>who moved with us.</h2></div><p>Read the full reviews and the latest feedback on the independent review profile.</p></div><div class="reviews-layout"><div class="review-proof"><span class="review-proof-icon">✦</span><span class="eyebrow">CUSTOMER REVIEWS</span><h3>Read the stories<br>behind the moves.</h3><p>Visit the public Trustpilot profile to explore recent reviews and current ratings.</p><a class="text-link" href="https://uk.trustpilot.com/review/removalsandstoragex.com" target="_blank" rel="noopener noreferrer">See reviews on Trustpilot ↗</a></div><article class="review-quote"><span class="quote-mark">“</span><blockquote>Excellent customer service</blockquote><p>Georgia · Office move · August 2026</p><a href="https://uk.trustpilot.com/review/removalsandstoragex.com" target="_blank" rel="noopener noreferrer">Read on Trustpilot ↗</a></article><article class="review-quote"><span class="quote-mark">“</span><blockquote>Responsive, prompt, friendly, professional.</blockquote><p>MaxH · Moving and storage · March 2026</p><a href="https://uk.trustpilot.com/review/removalsandstoragex.com" target="_blank" rel="noopener noreferrer">Read on Trustpilot ↗</a></article></div><div class="trust-emblems"><div><span class="emblem-mark">B</span><span><b>BAR membership</b><small>Stated by the company since March 2026</small></span></div><div><span class="emblem-mark">✦</span><span><b>Independent reviews</b><small>Read customer experiences on Trustpilot</small></span></div><div><span class="emblem-mark">✓</span><span><b>Written quotation</b><small>Confirm services and terms before booking</small></span></div></div></section>`}
