  if(req.method==='POST' && url.pathname==='/api/leads'){
    const ip=req.socket.remoteAddress||'unknown',now=Date.now(),recent=(leadAttempts.get(ip)||[]).filter(t=>now-t<15*60*1000);if(recent.length>=8){res.writeHead(429,{'content-type':'application/json','cache-control':'no-store'});res.end(JSON.stringify({ok:false,error:'Too many attempts. Please try again later.'}));return;}recent.push(now);leadAttempts.set(ip,recent);
    let raw=''; req.on('data',chunk=>{raw+=chunk; if(raw.length>100_000) req.destroy();});
    req.on('end',async()=>{try{const data=JSON.parse(raw),contact=data.contact||{};data.requestId||=createHash('sha256').update(JSON.stringify(data)).digest('hex');const required=['name','email','phone','service','requestId'];for(const key of required){const value=key==='service'||key==='requestId'?data[key]:contact[key];if(typeof value!=='string'||!value.trim())throw Error(`Please provide ${key}.`)}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact.email))throw Error('Please provide a valid email address.');if(data.privacyAcknowledged!==true)throw Error('Please acknowledge the enquiry privacy notice.');if(data.marketingConsent!==undefined&&typeof data.marketingConsent!=='boolean')throw Error('Invalid marketing consent.');await mkdir(path.join(root,'data'),{recursive:true});const log=path.join(root,'data','leads.jsonl');try{const existing=(await readFile(log,'utf8')).split('\n').filter(Boolean).map(x=>JSON.parse(x)).find(x=>x.requestId===data.requestId);if(existing){res.writeHead(200,{'content-type':'application/json','cache-control':'no-store'});res.end(JSON.stringify({ok:true,reference:existing.id,duplicate:true}));return}}catch(e){if(e.code!=='ENOENT')throw e}const lead={id:`RSX-${new Date().toISOString().slice(2,10).replaceAll('-','')}-${randomUUID().slice(0,6).toUpperCase()}`,status:'New',createdAt:new Date().toISOString(),...data};await appendFile(log,JSON.stringify(lead)+'\n',{mode:0o600});res.writeHead(201,{'content-type':'application/json','cache-control':'no-store'});res.end(JSON.stringify({ok:true,reference:lead.id}));}catch(e){res.writeHead(400,{'content-type':'application/json','cache-control':'no-store'});res.end(JSON.stringify({ok:false,error:e.message||'We could not save your enquiry.'}));}});return;
  }
