  const redirects={'/residential-removals':'/services/house-removals','/office-removals':'/business-moves','/packing-services':'/services/packing','/european-moving':'/services/european-removals','/about-us':'/about','/contact-us':'/contact'};
  if(req.method==='GET'&&redirects[route]){res.writeHead(301,{location:redirects[route]});res.end();return;}
